-- ====================================================================
-- NexusGrid PostgreSQL Production Database Dump
-- Compatible with Vercel Postgres (Neon), Supabase, AWS RDS, Neon.tech
-- Generated for Vercel Serverless Hosting
-- ====================================================================

SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- -----------------------------------------------------
-- Table: work_streams
-- -----------------------------------------------------
DROP TABLE IF EXISTS work_streams CASCADE;
CREATE TABLE work_streams (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    stream_code VARCHAR(32) NOT NULL,
    badge_label VARCHAR(64) NOT NULL,
    badge_class VARCHAR(64) NOT NULL,
    icon VARCHAR(16) NOT NULL,
    accent_color VARCHAR(16) NOT NULL,
    base_rate DECIMAL(10, 2) NOT NULL DEFAULT 35.00,
    unit VARCHAR(32) NOT NULL DEFAULT 'prompt',
    status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    description TEXT NOT NULL,
    qualification_required VARCHAR(120) NOT NULL,
    protocol_ref VARCHAR(120) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- -----------------------------------------------------
-- Table: assessment_questions
-- -----------------------------------------------------
DROP TABLE IF EXISTS assessment_questions CASCADE;
CREATE TABLE assessment_questions (
    id SERIAL PRIMARY KEY,
    question_text TEXT NOT NULL,
    option_a TEXT NOT NULL,
    option_b TEXT NOT NULL,
    option_c TEXT NOT NULL,
    option_d TEXT NOT NULL,
    correct_index INT NOT NULL DEFAULT 0
);

-- -----------------------------------------------------
-- Table: users
-- -----------------------------------------------------
DROP TABLE IF EXISTS users CASCADE;
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(180) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'contributor' CHECK (role IN ('admin', 'contributor')),
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
    auth_token VARCHAR(64) NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    last_login TIMESTAMPTZ NULL
);

-- -----------------------------------------------------
-- Table: tasks (110 Enterprise RLHF Dilemma Workstreams)
-- -----------------------------------------------------
DROP TABLE IF EXISTS tasks CASCADE;
CREATE TABLE tasks (
    id SERIAL PRIMARY KEY,
    task_uid VARCHAR(64) UNIQUE NOT NULL,
    category VARCHAR(100) NOT NULL,
    icon VARCHAR(16) NOT NULL DEFAULT '✳',
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    how_to_do_it TEXT NULL,
    what_to_submit VARCHAR(255) NULL,
    time_estimate VARCHAR(50) NOT NULL DEFAULT '40 minutes',
    no_ai_rule TEXT NULL,
    pay DECIMAL(10, 2) NOT NULL DEFAULT 25.00,
    difficulty_level VARCHAR(50) NOT NULL DEFAULT 'All levels',
    tag VARCHAR(20) NOT NULL DEFAULT 'OPEN',
    posted_hours_ago INT NOT NULL DEFAULT 1,
    stream_id VARCHAR(64) DEFAULT 'PREFERENCE_RANKING',
    prompt_text TEXT NULL,
    response_a TEXT NULL,
    response_b TEXT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- -----------------------------------------------------
-- Table: submissions
-- -----------------------------------------------------
DROP TABLE IF EXISTS submissions CASCADE;
CREATE TABLE submissions (
    id SERIAL PRIMARY KEY,
    sub_uid VARCHAR(64) UNIQUE NOT NULL,
    task_id VARCHAR(64) NOT NULL,
    task_title VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    contributor_name VARCHAR(120) NOT NULL,
    contributor_email VARCHAR(180) NOT NULL,
    response_text TEXT NOT NULL,
    pay DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    score DECIMAL(3, 1) NULL,
    auto_score DECIMAL(4, 2) NULL,
    dim_scores JSONB NULL,
    feedback TEXT NULL,
    submitted_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    reviewed_at TIMESTAMPTZ NULL
);
CREATE INDEX idx_submissions_email ON submissions (contributor_email);
CREATE INDEX idx_submissions_status ON submissions (status);
CREATE INDEX idx_submissions_submitted_at ON submissions (submitted_at);

-- -----------------------------------------------------
-- Table: account_controls
-- -----------------------------------------------------
DROP TABLE IF EXISTS account_controls CASCADE;
CREATE TABLE account_controls (
    id SERIAL PRIMARY KEY,
    email VARCHAR(180) UNIQUE NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'flagged' CHECK (status IN ('active', 'flagged', 'disabled')),
    country VARCHAR(100) NOT NULL,
    flagged_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- -----------------------------------------------------
-- Table: verified_contributors
-- -----------------------------------------------------
DROP TABLE IF EXISTS verified_contributors CASCADE;
CREATE TABLE verified_contributors (
    id SERIAL PRIMARY KEY,
    email VARCHAR(180) UNIQUE NOT NULL,
    doc_type VARCHAR(50) NOT NULL DEFAULT 'passport',
    verified_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

