INSERT INTO work_streams (id, name, category, icon, color, base_rate, status, stream_active_badge, instruction, created_at) VALUES ('PREFERENCE_RANKING', 'Preference Ranking (RLHF)', 'AI Model Alignment', 'layers', 'text-indigo-400', '45.00', 'ACTIVE', 'Stream Active', 'Evaluate two competing AI model outputs against the given prompt. Score coherence, factual accuracy, safety, and conciseness. Select an overall winner and provide at least 100 characters of technical justification.', '2026-11-04 14:38:28');
