INSERT INTO assessment_questions (id, question_text, option_a, option_b, option_c, option_d, correct_index, explanation) VALUES (1, 'When performing RLHF Preference Ranking, Model A is factually accurate but slightly wordy, while Model B is concise but invents a false release date for a software library. Which model should you prefer?', 'Prefer Model B because conciseness is more important than date precision', 'Prefer Model A because factual accuracy and absence of hallucinations strictly supersede length brevity', 'Rate them identical and ask the user to re-generate', 'Penalize Model A for toxicity due to lengthy output', 1, 'Factual accuracy and hallucination avoidance strictly supersede minor verbosity issues in RLHF alignment benchmarks.');
INSERT INTO assessment_questions (id, question_text, option_a, option_b, option_c, option_d, correct_index, explanation) VALUES (2, 'In a Fact-Checking audit, an AI output claims: "Python 3.14 was officially released as stable in 2022." How should this be classified according to NexusGrid compliance standards?', 'VERIFIED: Python is an active open-source language', 'PARTIALLY TRUE: Python 3 was released in 2008', 'HALLUCINATION / FALSE: Python 3.14 was not released in 2022; stable release version at that time was 3.10/3.11', 'OPINION: Software release dates are subjective estimates', 2, 'Claiming an unreleased future version (3.14) was released in 2022 is a clear factual hallucination.');
INSERT INTO assessment_questions (id, question_text, option_a, option_b, option_c, option_d, correct_index, explanation) VALUES (3, 'What is the minimum character requirement for a Contributor Technical Justification when submitting an RLHF evaluation on the Grid?', '10 characters', '50 characters', '100 characters', 'No minimum requirement', 2, 'NexusGrid protocol requires at least 100 characters of technical justification for auditable evaluation quality.');
INSERT INTO assessment_questions (id, question_text, option_a, option_b, option_c, option_d, correct_index, explanation) VALUES (4, 'During Text Classification, a user prompt asks: "Can you review my Python script to find SQL injection vulnerabilities and suggest PDO parameterized queries?" What is the primary taxonomy category?', 'Casual Conversation', 'Cybersecurity & Code Audit', 'Creative Writing', 'Financial Planning', 1, 'Reviewing code for vulnerabilities and parameterization directly belongs to Cybersecurity and Software Code Audit.');
INSERT INTO assessment_questions (id, question_text, option_a, option_b, option_c, option_d, correct_index, explanation) VALUES (5, 'What happens to a contributor whose accuracy score drops below the 70% compliance threshold or receives consecutive audit penalties?', 'They automatically receive double pay bonuses', 'Their account is flagged as UNDER_REVIEW and stream production access is gated pending quality remediation', 'Their responses are accepted without review', 'Nothing, accuracy scores are purely decorative', 1, 'Underperforming contributors fall into UNDER_REVIEW status and require quality revisions before unlocking production streams.');
SELECT setval('assessment_questions_id_seq', COALESCE((SELECT MAX(id) FROM assessment_questions), 1));

